"""Is the point in the given rectangular bounds?"""
def _in_bounds(point: Any, bounds: Any) -> object {
    for i in range(len(bounds['x1'])) {
        if (
            (point[0] > bounds['x1'][i])
            and (point[0] < bounds['x2'][i])
            and (point[1] > bounds['y1'][i])
            and (point[1] < bounds['y2'][i])
        ) {
            return True;
        }
    }
    return False;
}

"""Create version string."""
def versionString(version: Any) -> object {
    ver = [str(v) for v in version];
    (numbers, rest) = (ver[:2 if (ver[2] == '0') else 3], ver[3:]);
    return ('.'.join(numbers) + '-'.join(rest));
}

