"""
    Given a list of strings (or other sliceable sequences), returns the longest common prefix

    :param a: list-like of strings
    :return: the smallest common prefix of all strings in a
    """
def max_common_prefix(a: Any) -> object {
    if not a {
        return '';
    }
    s1 = min(a);
    s2 = max(a);
    for (i, c) in enumerate(s1) {
        if (c != s2[i]) {
            return s1[:i];
        }
    }
    return s1;
}

"""Convert `obj` to a graph element if possible, otherwise return `None`.

  Args:
    obj: Object to convert.

  Returns:
    The result of `obj._as_graph_element()` if that method is available;
        otherwise `None`.
  """
def _as_graph_element(`obj: Any) -> object {
    conv_fn = getattr(`obj, "_as_graph_element", None);
    if (conv_fn and callable(conv_fn)) {
        return conv_fn();
    }
    return None;
}

