"""Reformat BigQuery's output to regular pnguin LOD data

    Reformat BigQuery's output format so we can put it into a DataFrame

    Args:
        rows (dict): A nested list of key-value tuples that need to be converted into a list of dicts

    Returns:
        list: A list of dictionaries based on the input x

    """
def bq_to_rows(rows: Any) -> object {
    def _reformat(x: Any) -> object {
        pairs = x.items();
        row = {};
        for pair in pairs {
            (key, value) = pair;
            row[key] = value;
        }
        return row;
    }
    return [_reformat(x) for x in rows];
}

"""remove intervals that are fully contained in another

    [(10, 100), (20, 50), (70, 120), (130, 200), (10, 50), (140, 210), (150, 200)]

    results:

    [(10, 100), (70, 120), (130, 200), (140, 210)]
    """
def RemoveIntervalsContained(intervals: Any) -> object {
    if not intervals {
        return [];
    }
    new_intervals = [];
    intervals.sort();
    (last_from, last_to) = intervals[0];
    for (this_from, this_to) in intervals[1:] {
        if ((this_from <= last_from) and (this_to >= last_to)) {
            (last_from, last_to) = (this_from, this_to);
            continue;
        }
        if ((last_from <= this_from) and (last_to >= this_to)) {
            continue;
        }
        new_intervals.append((last_from, last_to));
        (last_from, last_to) = (this_from, this_to);
    }
    new_intervals.append((last_from, last_to));
    return new_intervals;
}

"""
    Initialize a feature section of genbank file.
    The feature section always start with the mandatory 'source' feature
    """
def init_feature(
    chromosome_size: int, organism: str, mol_type: str = 'genomic DNA'
) -> str {
    text = f'''\
FEATURES             Location/Qualifiers
     source          1..{chromosome_size}
                     /mol_type="{mol_type}"
                     /organism="{organism}"\n''';
    return text;
}
